// Parity with the Python client on what each pattern yields.
//
// `pattern-vectors.json` is generated by `gen-pattern-vectors.py` from the
// Python client's patterns and committed; here the TS client builds the same
// patterns, case by case under the same names, and must yield the same values.
// A case that draws seeds the random context first: both clients draw from the
// same core generator, so the draws are asserted exactly too.
//
// Exact everywhere but the transcendental operators (`midicps`), which go
// through libm and are held to one f32 ulp -- the posture `docs/decisions.md`
// records under "Native<->wasm render parity is a tight tolerance".

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

import { loadCore } from "../src/base/core.ts";
import { seed } from "../src/base/rand.ts";
import * as b from "../src/base/builtins.ts";
import {
    pavaroh,
    pbind,
    pclump,
    pcollect,
    pdelta,
    pdiff,
    pdrop,
    pdur,
    pflatten,
    pgate,
    platch,
    plen,
    pprorate,
    preject,
    pselect,
    pstutter,
    ptrace,
    pwhile,
    pwrap,
    pdfsm,
    pfsm,
    place,
    placep,
    pshuffle,
    pslide,
    pswitch,
    pswitch1,
    ptuple,
    pwalk,
    pwrand,
    pxrand,
    INF,
    pbeta,
    pbrown,
    pcauchy,
    pexprand,
    pgauss,
    pgbrown,
    phprand,
    plprand,
    pmeanrand,
    ppoisson,
    pprob,
    pvalue,
    pconst,
    pfunc,
    pgeom,
    pn,
    pnarop,
    prand,
    pseq,
    pser,
    pseries,
    pwhite,
} from "../src/seq/index.ts";
import type { Event, Pattern } from "../src/seq/index.ts";

await loadCore();

const TAKE = 8;

/** A condition true twice, then false: `pwhile`'s test. */
const twice = (): (() => boolean) => {
    let count = 0;
    return () => ++count <= 2;
};

/** name -> the pattern; the names are `gen-pattern-vectors.py`'s. */
const CASES: Record<string, () => Pattern<unknown>> = {
    pseq: () => pseq([1, 2, 3], 2),
    pseq_nested: () => pseq<number>([1, pseq([8, 9]), 2]),
    pseq_endless: () => pseq([1, 2], INF),
    pser: () => pser([1, 2, 3], 5),
    pconst: () => pconst(7, 3),
    pseries: () => pseries(0, 2.5, 4),
    pgeom: () => pgeom(1, 3, 5),
    pn: () => pn(pseq([1, 2]), 3),
    pfunc: () => pfunc(() => 4, 3),
    pwhite: () => pwhite(-1, 1, 6),
    prand: () => prand([10, 20, 30], 6),
    add: () => pseq([74, 60, 46]).add(2),
    mul_shorter: () => pseq([1, 2, 3]).mul(pseq([10, 20])),
    ops_chain: () => pseries(0, 1, 6).mul(7).mod(12).max(3),
    midicps: () => pseq([57, 69, 81]).midicps(),
    linlin: () => pnarop("linlin", pseq([0, 0.25, 1, 2]), 0, 1, 10, 20),
    clip: () => pnarop("clip", pseq([-2, 0.5, 3]), 0, 1),
    random_ops: () => pwhite(0, 1, 6).mul(100).floor(),
    linlin_method: () => pseq([0, 0.5, 1, 2]).linlin(0, 1, 200, 800, "max"),
    lincurve_method: () => pseq([0, 0.25, 0.5, 1]).lincurve(0, 1, 0, 10, -4),
    fold_method: () => pseq([-0.5, 1.5, 2.25]).fold(0, 1),
    blend: () => pseq([0, 10, 20]).blend(pseq([100, 50, 0]), 0.25),
    angles: () => pseq([0, 90, 270]).degrad().raddeg(),
    moddif: () => pseq([0.1, 0.9, 0.5]).moddif(0.2),
    bilin: () => pseq([0, 0.25, 0.5, 0.75, 1]).bilin(0.5, 0, 1, 10, 0, 100),
    bit_ops: () => pseq([0, 5]).bitnot().idiv(2).bitand(7),
    not: () => pseq([-1, 0, 1]).not(),
    draws: () => pseq([10, 10, 10]).rand().add(pseq([1, 1, 1]).exprand(2)),
    builtin_midicps: () => b.midicps(pseq([60, 72])),
    builtin_reflected: () => b.sub(100, pseq([1, 2, 3])),
    builtin_by_name: () => b.degkey(pseq([0, 3, 7, -1]), [0, 2, 4, 5, 7, 9, 11]),
    pvalue: () => pseq<number>([pvalue(pseq([1, 2])), pvalue(3)]),
    pseries_stepped: () => pseries(0, pseq([1, 2, 3])),
    pgeom_grown: () => pgeom(1, pseq([2, 3]), 3),
    pwhite_bounds: () => pwhite(pseq([0, 10, 20]), pseq([1, 11, 21])),
    pexprand: () => pexprand(100, 1000, 6),
    plprand: () => plprand(0, 10, 6),
    phprand: () => phprand(0, 10, 6),
    pmeanrand: () => pmeanrand(0, 10, 6),
    pbeta: () => pbeta(-1, 1, 0.5, 2, 6),
    pcauchy: () => pcauchy(5, 0.5, 6),
    pgauss: () => pgauss(60, 3, 6),
    ppoisson: () => ppoisson(2.5, 6),
    pbrown: () => pbrown(0, 1, 0.25, 8),
    pgbrown: () => pgbrown(100, 400, 0.2, 8),
    pprob: () => pprob([0, 1, 4, 1, 0], 48, 72, null, 8),
    pseq_offset: () => pseq([1, 2, 3], 2, 1),
    pser_offset: () => pser([1, 2, 3], 5, 2),
    pxrand: () => pxrand([1, 2, 3], 8),
    pwrand: () => pwrand([1, 2, 3], [1, 0, 3], 8),
    pshuffle: () => pshuffle([1, 2, 3, 4], 2),
    pslide: () => pslide([1, 2, 3, 4, 5], 3, 3, 1),
    pslide_nowrap: () => pslide([1, 2, 3], 4, 2, 1, 0, false),
    pwalk: () => pwalk([1, 2, 3, 4], pseq([1], 8), pseq([1, -1], INF)),
    pwalk_random: () => pwalk([1, 2, 3, 4, 5]),
    place: () => place([1, [2, 3], [4, 5, 6]], 3),
    placep: () => placep<number>([pseq([1, 2]), pseq([10, 20, 30])], 5),
    ptuple: () => ptuple<number>([pseq([1, 2]), pseq([10, 20, 30])], 2),
    pswitch: () => pswitch<number>([pseq([1, 2]), 9], pseq([0, 1, 0])),
    pswitch1: () => pswitch1<number>([pseq([1, 2, 3]), pseq([10, 20])], pseq([0, 1, 0, 1])),
    pfsm: () => pfsm([[0], 1, [1], 2, [0, 2], 3, [1, 3], null, null], 2),
    pcollect: () => pcollect((x: number) => x * x, pseq([1, 2, 3])),
    pselect: () => pselect((x: number) => x % 3 === 0, pseries(0, 1, 12)),
    preject: () => preject((x: number) => x % 3 === 0, pseries(0, 1, 9)),
    pdrop: () => pdrop(pseries(0, 1, 6), 2),
    plen: () => plen(pseries(5, 5), 4),
    pstutter: () => pstutter(pseq([1, 2, 3]), pseq([2, 0, 3])),
    platch: () => platch(pseries(0, 1), pseq([true, false, false, true, false, true])),
    pwhile: () => pwhile(twice(), pseq([7, 8])),
    pwrap: () => pwrap(pseq([-1, 5, 2.5]), 0, 4),
    pclump: () => pclump(pseries(0, 1, 5), 2),
    pflatten: () => pflatten(pseq<unknown>([[1, [2, 3]], 4]), 1),
    pdiff: () => pdiff(pseq([1, 4, 9, 16])),
    pprorate: () => pprorate(pseq([1, 2]), pseq<number | number[]>([0.25, [0.5, 0.25, 0.25]])),
    pavaroh: () => pavaroh(pseq([0, 2, 4, 2, 0]), [0, 2, 4, 5, 7, 9, 11], [0, 1, 3, 5, 7, 8, 10]),
    pdur: () => pcollect((e: Event) => e.delta(), pdur(2.5, pbind({ dur: 1, degree: pseq([0, 1, 2, 3]) }))),
    pdelta: () => pcollect((e: Event) => e.delta(), pdelta(1.5, pbind({ dur: 0.5, degree: pseq([0, 1]) }))),
    pgate: () => pcollect(
        (e: Event) => e.get("x"),
        plen(pbind({ n: pn(pseq([0, 1]), INF, "g"), x: pgate(pseries(0, 1), INF, "g") }), 6),
    ),
    ptrace_passes: () => ptrace(pseq([1, 2]), "| "),
    pdfsm: () => pdfsm([
        pseq([0, 1, 1, 0]),
        { 0: [0, 1], 1: [1, 2], default: [0, 3] },
        { 0: [0, 4], default: [1, 5] },
    ]),
};

// The draws that go through `exp`, `ln`, `pow`, `tan` or `sin` are libm's, and
// wasm's differs from the native one in the last bits.
const TRANSCENDENTAL = new Set([
    "midicps", "builtin_midicps", "lincurve_method", "pexprand", "pbeta", "pcauchy",
    "pgauss", "ppoisson",
]);

const vectors: Record<string, { seed: number | null; values: number[] }> = JSON.parse(
    await readFile(new URL("./pattern-vectors.json", import.meta.url), "utf8"),
);

const take = (p: Pattern<unknown>): number[] => {
    const out: number[] = [];
    let taken = 0;
    for (const x of p) {
        if (taken++ === TAKE) break;
        // A value that is an array (`ptuple`) is written flat.
        for (const v of Array.isArray(x) ? x : [x]) out.push(Number(v));
    }
    return out;
};

const ulp = (x: number): number => {
    const f = new Float32Array([Math.abs(x)]);
    const bits = new Uint32Array(f.buffer);
    bits[0] = bits[0]! + 1;
    return f[0]! - Math.fround(Math.abs(x));
};

test("every case is on both sides", () => {
    assert.deepEqual(Object.keys(CASES).sort(), Object.keys(vectors).sort());
});

for (const [name, expected] of Object.entries(vectors)) {
    test(`${name} yields what the Python client's yields`, () => {
        if (expected.seed !== null) seed(expected.seed);
        const got = take(CASES[name]!());
        assert.equal(got.length, expected.values.length);
        got.forEach((v, i) => {
            const want = expected.values[i]!;
            if (TRANSCENDENTAL.has(name)) assert.ok(Math.abs(v - want) <= ulp(want), `${v} vs ${want}`);
            else assert.equal(v, want);
        });
    });
}
